import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;
const wake = new AbortController();

const beatStmt = db.prepare('INSERT INTO heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at');
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}

const nowIso = () => new Date().toISOString();

// Any job left running belongs to a previous worker that died or was stopped mid-attempt: requeue it.
db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'").run(nowIso());

const pickStmt = db.prepare(`
  UPDATE jobs
  SET status = 'running', attempts = MIN(attempts + 1, ${MAX_ATTEMPTS}), progress = 0, updated_at = ?
  WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
    AND status = 'queued'
  RETURNING *
`);
const progressStmt = db.prepare("UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const completeStmt = db.prepare("UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'");
const failStmt = db.prepare("UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const retryStmt = db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const requeueStmt = db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'");

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        failStmt.run('transient failure', nowIso(), job.id);
      } else {
        retryStmt.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
      }
      return;
    }
    await sleep(STEP_MS);
    if (stopping) {
      // Graceful shutdown mid-attempt: hand the job back so the next worker reprocesses it.
      requeueStmt.run(nowIso(), job.id);
      return;
    }
    if (step < job.steps) progressStmt.run(step, nowIso(), job.id);
  }
  completeStmt.run(job.input.toUpperCase(), nowIso(), job.id);
}

async function main(): Promise<void> {
  beat();
  const timer = setInterval(beat, HEARTBEAT_MS);
  console.log('worker started');
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = pickStmt.get(nowIso(), Date.now()) as JobRow | undefined;
    } catch (e) {
      console.error('failed to pick job', e);
    }
    if (job) {
      try {
        await processJob(job);
      } catch (e) {
        console.error(`job ${job.id} processing error`, e);
      }
      continue;
    }
    try {
      await sleep(POLL_MS, undefined, { signal: wake.signal });
    } catch {
      // aborted by shutdown
    }
  }
  clearInterval(timer);
  try {
    db.prepare('DELETE FROM heartbeat').run();
  } catch {
    // ignore
  }
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake.abort();
  });
}

await main();

